package main

import (
	"embed"
	"fmt"
	"io/fs"
)

//go:embed files/one.txt
var one string

//go:embed files
var all embed.FS

func main() {
	fmt.Printf("%q\n", one)
	b, err := all.ReadFile("files/two.txt")
	fmt.Printf("%q %v\n", string(b), err)
	entries, _ := all.ReadDir("files")
	for _, e := range entries {
		fmt.Println(e.Name(), e.IsDir())
	}
	var visited []string
	fs.WalkDir(all, ".", func(p string, d fs.DirEntry, err error) error {
		visited = append(visited, p)
		return nil
	})
	fmt.Println(visited)
	fmt.Println(fs.ValidPath("."), fs.ValidPath("files/one.txt"), fs.ValidPath("/files"))
}

